<script lang="ts">let {data}=$props();let search=$state(''),filter=$state('all');const posts=$derived(data.posts.filter(p=>(filter==='all'||(filter==='draft'?!p.isPublished:p.isPublished))&&p.title.includes(search)));</script>
<svelte:head><title>お知らせ | Autumn Book</title></svelte:head>
<section class="news-list"><header><h1>お知らせ</h1>{#if data.user?.role==='admin'}<a class="new" href="/admin/news/new">＋ お知らせを作成</a>{/if}</header><div class="filters"><nav>{#each [{id:'all',label:'すべて'},{id:'draft',label:'下書き'},{id:'published',label:'公開中'}] as f}<button class:active={filter===f.id} onclick={()=>filter=f.id}>{f.label}</button>{/each}</nav><input bind:value={search} aria-label="お知らせを検索" placeholder="タイトルで検索"/><span>{posts.length}件</span></div><div class="cards">{#each posts as post}<a class="card" href={'/admin/news/'+post.id}>{#if post.coverImageUrl}<img src={post.coverImageUrl} alt={post.coverImageAlt||''}/>{:else}<span class="no-image">お知らせ</span>{/if}<div><span class:published={post.isPublished} class="status">{post.isPublished?'公開中':'下書き'}</span><time>{post.publishedAt}</time><h2>{post.title}</h2></div><span class="arrow">→</span></a>{/each}{#if !posts.length}<p>該当するお知らせはありません。</p>{/if}</div></section>
<style>.news-list{max-width:1200px;margin:auto}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}h1{font-size:28px;font-weight:600}.new{padding:12px 18px;border-radius:7px;background:#57764a;color:white;font-size:13px}.new:hover{background:#3f5e32}.filters{display:flex;align-items:center;gap:12px;margin-bottom:18px;font-size:12px;color:#89947f}.filters nav{display:flex;gap:4px}.filters button{padding:8px 12px;border-radius:6px}.filters button:hover,.filters .active{background:#e8efdf;color:#4d693d}.filters input{margin-left:auto;padding:10px;border:1px solid #dfe5d6;border-radius:7px;background:white}.cards{display:grid;gap:12px}.card{display:flex;align-items:center;gap:20px;border:1px solid #e0e6d8;border-radius:10px;padding:18px;background:white;transition:box-shadow .15s,border-color .15s}.card:hover{border-color:#acbd97;box-shadow:0 3px 15px #31472610}.card img,.no-image{width:110px;height:74px;object-fit:cover;border-radius:5px;flex:none}.no-image{display:grid;place-items:center;background:#f3f5ee;color:#b0b8a6;font-size:11px}.card h2{font-size:16px;font-weight:550;margin-top:10px}.status{font-size:11px;padding:3px 9px;border-radius:10px;background:#f1f0ea;color:#8c947e}.status.published{background:#eaf3df;color:#6d8855}time{font-size:12px;color:#929d85;margin-left:12px}.arrow{margin-left:auto;color:#98a58a}@media(max-width:600px){.filters{flex-wrap:wrap}.filters nav{width:100%}.filters input{margin:0;flex:1;min-width:0}.card{padding:12px;gap:12px}.card img,.no-image{width:70px;height:60px}.card h2{font-size:14px}.new{padding:10px;font-size:12px}}</style>
